# final self-check: exactly this seat's id list, each file parses and has required fields
written = 0
for cid in IDS:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid
    for k in ("prediction_text", "basis", "confidence", "trigger"):
        assert k in d, (cid, k)
    for k in ("changed_main", "reserve_used", "disputed", "reason"):
        assert k in d["trigger"], (cid, k)
    assert d["basis"].splitlines()[0].strip() == "liuyao", cid
    written += 1
assert written == 20, written
cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print("ALL written:", written, "changed_main:", cm, "reserve_used:", ru, "disputed:", di)
